import{bV as t,aL as a,u as r,G as o}from"./chunks/framework.DvBUyM1S.js";const u=JSON.parse('{"title":"2022提高国内访问 Github 速度的 5 种方法！","description":"","frontmatter":{"title":"2022提高国内访问 Github 速度的 5 种方法！","date":"2021-02-28T20:55:40.000Z","permalink":"/pages/a782fe/","categories":["GitHub"],"tags":[null],"sticky":1},"headers":[],"relativePath":"06.工具/05.GitHub/01.2022提高国内访问Github速度的5种方法.md","filePath":"06.工具/05.GitHub/01.2022提高国内访问Github速度的5种方法.md","lastUpdated":1652283432000}'),s={name:"06.工具/05.GitHub/01.2022提高国内访问Github速度的5种方法.md"};function l(n,e,i,h,p,c){return a(),r("div",null,[...e[0]||(e[0]=[o(`<h1 id="_2022提高国内访问-github-速度的-5-种方法" tabindex="-1">2022提高国内访问 Github 速度的 5 种方法！ <a class="header-anchor" href="#_2022提高国内访问-github-速度的-5-种方法" aria-label="Permalink to &quot;2022提高国内访问 Github 速度的 5 种方法！&quot;">​</a></h1><h2 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;前言&quot;">​</a></h2><ul><li>MuaCloud 机场</li><li>利用第三方镜像下载</li><li>通过代理网站下载</li><li>Gitee中转fork仓库下载</li><li>修改 HOSTS 文件进行加速</li></ul><h3 id="muacloud-机场" tabindex="-1">MuaCloud 机场 <a class="header-anchor" href="#muacloud-机场" aria-label="Permalink to &quot;MuaCloud 机场&quot;">​</a></h3><p><a href="https://muacloud.live/auth/register?code=1000" target="_blank" rel="noreferrer">MuaCloud 机场</a>，注册账号，在<strong>商店购买套餐</strong>然后首页<strong>复制订阅地址</strong>导入<code>Clash</code>开启代理，访问<a href="https://www.google.com/search?q=site%3Afeyoudao.cn" target="_blank" rel="noreferrer">Google</a>测试是否成功。</p><p><img src="https://feyoudao.oss-cn-hongkong.aliyuncs.com/mweb/20220416-16501041588874.jpg" alt="" loading="lazy"><img src="https://feyoudao.oss-cn-hongkong.aliyuncs.com/mweb/20220416-16501046070820.jpg" alt="" loading="lazy"></p><blockquote><p>教程 <a href="https://muacloud.live/user/tutorial?os=Windows&amp;client=Clash" target="_blank" rel="noreferrer">https://muacloud.live/user/tutorial?os=Windows&amp;client=Clash</a></p></blockquote><p><strong>Clash工具</strong></p><ul><li><p><a href="https://github.com/WhoJave/clash/releases" target="_blank" rel="noreferrer">Clash Download 官网</a></p></li><li><p><a href="https://sabrinathings.lanzouq.com/iRHtH01dh6le" target="_blank" rel="noreferrer">Clash for Windows 汉化版</a></p></li><li><p><a href="./[https://install.appcenter.ms/users/clashx/apps/clashx-pro/distribution_groups/public.html">ClashX Pro for Mac</a></p></li></ul><p><code>ClashX Pro</code> 可开启增强模式下终端会走代理流量，<code>克隆仓库</code>、<strong>安装依赖包</strong>等可节省<code>70%</code>~<code>90%</code>时间，缺点可能影响到项目开发，添加忽略网站地址。</p><blockquote><p>Windows用户可以借助<code>Proxifier</code>软件实现全局代理。</p></blockquote><h3 id="利用第三方镜像下载" tabindex="-1">利用第三方镜像下载 <a class="header-anchor" href="#利用第三方镜像下载" aria-label="Permalink to &quot;利用第三方镜像下载&quot;">​</a></h3><p><strong>第一种 安装油猴插件和脚本</strong></p><ul><li><a href="https://chrome.google.com/webstore/detail/tampermonkey/dhdgffkkebhmkfjojejmpbldmpobfkfo" target="_blank" rel="noreferrer">油猴插件</a></li><li><a href="https://greasyfork.org/zh-CN/scripts/412245-github-%E5%A2%9E%E5%BC%BA-%E9%AB%98%E9%80%9F%E4%B8%8B%E8%BD%BD" target="_blank" rel="noreferrer">Github 增强 - 高速下载</a></li></ul><p>为 <code>Github</code> 的 <code>Git Clone</code>、<code>Release</code>、<code>Raw</code>、<code>Code(ZIP)</code> 等文件添加 高速下载（加速下载）。 <img src="https://feyoudao.oss-cn-hongkong.aliyuncs.com/mweb/20220226-16458653745716.jpg" alt="" loading="lazy"></p><p><strong>第二种 安装GitHub加速插件</strong></p><ul><li><a href="https://chrome.google.com/webstore/detail/github%E5%8A%A0%E9%80%9F/ffjjnphohkfckeplcjflmgneebafggej" target="_blank" rel="noreferrer">GitHub加速</a><img src="https://feyoudao.oss-cn-hongkong.aliyuncs.com/mweb/20220226-16458655418341.jpg" alt="" loading="lazy"></li></ul><p>提供<code>Release</code>、<code>Code(ZIP)</code> <code>tag</code>文件加速。</p><p><img src="https://feyoudao.oss-cn-hongkong.aliyuncs.com/mweb/20220226-16458734852084.jpg" alt="" loading="lazy"></p><h3 id="通过代理网站下载" tabindex="-1">通过代理网站下载 <a class="header-anchor" href="#通过代理网站下载" aria-label="Permalink to &quot;通过代理网站下载&quot;">​</a></h3><p><strong>Release、Code(ZIP) 文件加速：</strong></p><ul><li><a href="https://gh.api.99988866.xyz" target="_blank" rel="noreferrer">https://gh.api.99988866.xyz</a></li><li><a href="https://github.rc1844.workers.dev" target="_blank" rel="noreferrer">https://github.rc1844.workers.dev</a></li><li><a href="https://ghgo.feizhuqwq.workers.dev" target="_blank" rel="noreferrer">https://ghgo.feizhuqwq.workers.dev</a></li><li><a href="https://git.yumenaka.net" target="_blank" rel="noreferrer">https://git.yumenaka.net</a></li><li><a href="https://github.com.cnpmjs.org" target="_blank" rel="noreferrer">https://github.com.cnpmjs.org</a></li><li><a href="https://mirror.ghproxy.com/" target="_blank" rel="noreferrer">https://mirror.ghproxy.com/</a></li><li><a href="https://ghproxy.com/" target="_blank" rel="noreferrer">https://ghproxy.com/</a></li><li><a href="https://toolwa.com/github/" target="_blank" rel="noreferrer">https://toolwa.com/github/</a></li></ul><p><strong>Git Clone 加速：</strong></p><ul><li><a href="https://github.do" target="_blank" rel="noreferrer">https://github.do</a></li><li><a href="https://gitclone.com" target="_blank" rel="noreferrer">https://gitclone.com</a></li><li><a href="https://hub.fastgit.xyz" target="_blank" rel="noreferrer">https://hub.fastgit.xyz</a></li><li><a href="https://ghproxy.com" target="_blank" rel="noreferrer">https://ghproxy.com</a></li><li><a href="https://hub.0z.gs" target="_blank" rel="noreferrer">https://hub.0z.gs</a></li></ul><p>具体哪个速度快，请自行找一些大文件来测速。</p><h3 id="gitee中转fork仓库下载" tabindex="-1">Gitee中转fork仓库下载 <a class="header-anchor" href="#gitee中转fork仓库下载" aria-label="Permalink to &quot;Gitee中转fork仓库下载&quot;">​</a></h3><p>访问 <code>gitee</code> 网站并登录，在顶部选择“从<code> GitHub/GitLab</code> 导入仓库” 如下</p><p><img src="https://feyoudao.oss-cn-hongkong.aliyuncs.com/mweb/20220226-16458768942842.jpg" alt="" loading="lazy"></p><p>在页面中粘贴你的Github仓库地址，点击导入即可</p><p><img src="https://feyoudao.oss-cn-hongkong.aliyuncs.com/mweb/20220226-16458769944926.jpg" alt="" loading="lazy"> 导入成功，<code>git clone</code>仓库，下载速度可以达到<code>2MB/s</code>，就是有点费事。</p><h3 id="修改hosts文件进行加速" tabindex="-1">修改Hosts文件进行加速 <a class="header-anchor" href="#修改hosts文件进行加速" aria-label="Permalink to &quot;修改Hosts文件进行加速&quot;">​</a></h3><p>自从 2021.3 月初某会开始，很多地区已经<strong>间歇性无法访问</strong> Github 了。 这种情况无论是改 DNS 还是改 Hosts 都没用，因为对 Github 域名 SNI 干扰/封锁，<strong>任意 IP 指向 Github 去访问时，该 IP 的 443 端口就会超时 3 分钟！</strong> 因为是随机干扰的，所以有时候会碰到 “短暂” 可用的 IP</p><blockquote><p>有兴趣可以看看这篇详细讲解分析的文章：<a href="https://www.v2ex.com/t/758568" target="_blank" rel="noreferrer">https://www.v2ex.com/t/758568</a></p></blockquote><p>所以修改HOSTS文件进行加速方法是否还有效，可以自测。 <strong>下载修改HOSTS小工具</strong></p><ul><li><a href="https://swh.app/zh/" target="_blank" rel="noreferrer">SwitchHosts -修改HOSTS小工具</a></li></ul><p><strong>定时同步</strong></p><p>添加一条规则：</p><ul><li>方案名：GitHub</li><li>类型：远程</li><li>URL 地址：<code>https://gitee.com/ineo6/hosts/raw/master/hosts</code></li><li>自动更新：1个小时</li></ul><p><img src="https://feyoudao.oss-cn-hongkong.aliyuncs.com/mweb/20220226-16458775909003.jpg" alt="" loading="lazy"></p><p><strong>刷新DNS缓存</strong></p><p>打开终端，输入对应命令</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// Mac用户</span></span>
<span class="line"><span>sudo killall -HUP mDNSResponder</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// Win</span></span>
<span class="line"><span>ipconfig /flushdns</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><blockquote><p>原文地址：<a href="https://github.com/ineo6/hosts" target="_blank" rel="noreferrer">https://github.com/ineo6/hosts</a></p></blockquote><p>有兴趣可以阅读文章<a href="https://mp.weixin.qq.com/s/A37XnD3HdcGSWUflj6JujQ" target="_blank" rel="noreferrer">SwitchHosts! 还能这样管理 hosts</a>，后悔没早点用 了解详情，里面有介绍以及各个平台刷新 DNS 缓存的方法。</p><p><strong>参考</strong></p><ul><li><a href="https://github.com/ineo6/hosts" target="_blank" rel="noreferrer">https://github.com/ineo6/hosts</a></li><li><a href="https://www.beiwangshan.com/205.html" target="_blank" rel="noreferrer">https://www.beiwangshan.com/205.html</a></li><li><a href="https://greasyfork.org/zh-CN/scripts/412245-github-%E5%A2%9E%E5%BC%BA-%E9%AB%98%E9%80%9F%E4%B8%8B%E8%BD%BD" target="_blank" rel="noreferrer">https://greasyfork.org/zh-CN/scripts/412245-github-增强-高速下载</a></li></ul>`,46)])])}const d=t(s,[["render",l]]);export{u as __pageData,d as default};
